        if color == bg or count < 2:
            continue
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color]
        # Continue a diagonal ray from adjacent same-color diagonal cells.
        for r, c in pts:
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color):
                    continue
                for sr, sc in ((dr, dc), (-dr, -dc)):
                    y, x = r, c
                    while 0 <= y + sr < h and 0 <= x + sc < w:
                        y += sr
                        x += sc
                        if out[y][x] == bg:
                            out[y][x] = color
                        elif out[y][x] != color:
                            break
    return out
